// State-card notes from scripts/notes.json. Each cites a source key in SOURCES and, for Bleek, a page.
export const NOTES = [{"state": "USA", "src": "bleek", "page": 9, "text": "Bleek codes exploration from 1939, when Roosevelt set up the Advisory Committee on Uranium, pursuit from January 1942, and acquisition in 1945 with the Trinity test on 16 July."}, {"state": "USA", "src": "bleek", "page": 9, "text": "Singh and Way start their data in 1945, so they code the United States as acquiring in that year and never code exploration or pursuit (Bleek, note 27)."}, {"state": "RUS", "src": "bleek", "page": 10, "text": "Bleek codes the Soviet Union exploring from late 1942, pursuing from February 1943, when the State Defense Committee concentrated nuclear research in a new laboratory, and acquiring in 1949 after the test of 29 August. Singh and Way code pursuit from 1945, their first year of data."}, {"state": "GBR", "src": "bleek", "page": 10, "text": "Bleek codes exploration from 1940 (the MAUD Committee), pursuit from September 1941 (Tube Alloys) and acquisition in 1952 after the first British test on 3 October. Singh and Way code exploration from 1945 and pursuit from 1947."}, {"state": "FRA", "src": "bleek", "page": 11, "text": "Bleek codes exploration from October 1945, when France created its Atomic Energy Commission, pursuit from 1954 and acquisition in 1960 after the first test on 13 February. Jo and Gartzke date pursuit to Mendès-France's authorization of 26 December 1954; Bleek notes that no formal order may ever have been sent."}, {"state": "CHN", "src": "bleek", "page": 12, "text": "Bleek codes exploration from May 1952, pursuit from the Central Secretariat meeting of 15 January 1955, during the first Taiwan Strait crisis, and acquisition in 1964 after the test of 16 October. Jo and Gartzke date the program to 1956."}, {"state": "ISR", "src": "bleek", "page": 13, "text": "Bleek codes exploration from 1949, pursuit from 1955, and acquisition in 1967, following Avner Cohen's account that Israeli teams assembled improvised but operational devices in May of that year."}, {"state": "ISR", "src": "bleek", "page": 14, "text": "Bleek calls Singh and Way's original acquisition date of 1972 'unequivocally too late'. Jo and Gartzke use 1966; Way's 2012 update uses 1969 (note 55)."}, {"state": "ZAF", "src": "bleek", "page": 15, "text": "South Africa is the one state in these data that built nuclear weapons and gave them up. Bleek codes exploration from 1969, pursuit from 1974, when Prime Minister Vorster approved a limited nuclear explosive capability, and acquisition in 1979, when the first complete device was assembled."}, {"state": "ZAF", "src": "bleek", "page": 15, "text": "On 26 February 1990 de Klerk ordered the program ended and all weapons dismantled; dismantling began in July 1990, and by 6 September 1991 the HEU had been removed from the weapons (Albright, quoted by Bleek). Bleek and Jo and Gartzke code the return to no activity in 1991; Singh and Way's original coding used 1994, when all components were destroyed."}, {"state": "PAK", "src": "bleek", "page": "15–16", "text": "Bleek codes exploration and pursuit together from January 1972, when Bhutto, a month after the defeat by India, authorized a weapons program, and acquisition in 1987, on a former CIA official's account that the U.S. had an intelligence basis for not certifying Pakistan from 1987 on. Singh and Way's original coding put acquisition in 1990."}, {"state": "PAK", "src": "way11", "text": "Way's February 2011 file codes Pakistan as pursuing 1972–1986 and lists no acquisition; the June 2012 revision adds 'Acquire, 1987 -'."}, {"state": "IND", "src": "bleek", "page": 17, "text": "India is the hardest case to code. Bleek has exploration from 1948, pursuit from late 1964 under Shastri, a step back to exploration around June 1966, pursuit again from September 1972, exploration after the May 1974 test, and pursuit again from 1980."}, {"state": "IND", "src": "bleek", "page": 19, "text": "Bleek does not treat the 1974 test as acquisition and codes acquisition in 1987; Way and Jo and Gartzke use 1988. Singh and Way's original coding counted 1974 as acquisition and dropped India back in 1975 (notes 76, 88)."}, {"state": "PRK", "src": "bleek", "page": 20, "text": "Bleek codes exploration from 1962, pursuit from 1980, when a U.S. satellite found a second, larger reactor under construction at Yongbyon, and acquisition in 2006 after the first nuclear test. Jo and Gartzke date pursuit to 1982; Way codes exploration from 1965."}, {"state": "YUG", "src": "bleek", "page": 21, "text": "Bleek codes exploration from 1949 and pursuit from 1953, deactivated in 1962; exploration again from 1974 and pursuit from 1982 (“Project A”), ended in 1987. Way codes both episodes as exploration only, and notes that new evidence may justify moving them to pursuit."}, {"state": "KOR", "src": "bleek", "page": 22, "text": "Bleek codes exploration from 1969, after the Guam Doctrine and the withdrawal of a U.S. division, and pursuit from 1970, when Park Chung Hee reportedly approved a secret plan to build nuclear weapons."}, {"state": "KOR", "src": "bleek", "page": 24, "text": "Park ordered a halt under U.S. pressure in 1975 but, by one account, restarted the work in 1976. Bleek codes pursuit as continuous and ending in 1981, after Chun Doo-hwan disbanded the program and the Reagan administration bargained for its end. Jo and Gartzke end the program in 1975, when South Korea ratified the NPT."}, {"state": "LBY", "src": "bleek", "page": 24, "text": "Bleek and Singh and Way both code exploration and pursuit from 1970, when a senior Libyan official first visited China to try to buy nuclear weapons. Jo and Gartzke do not code Libya at all."}, {"state": "LBY", "src": "way12", "text": "Way: “in many of middle years, activity slowed to a crawl. Coding a stop requires clear and definitive renunciation maintained for at least three years, so the pursuit is coded as continuous over 33 years”. Way adds that the program revived with Khan network deals in the mid-1980s and restarted “with great vigor in 1995.”"}, {"state": "LBY", "src": "bush2003", "text": "On 19 December 2003 President Bush announced that Qadhafi had publicly committed to disclose and dismantle all weapons of mass destruction programs and to admit international inspectors. The next year Libya let the U.S. airlift its nuclear equipment and materials out (Bleek, p. 25)."}, {"state": "BRA", "src": "bleek", "page": 25, "text": "Bleek codes exploration from 1966 and pursuit from 1975, the start of the military's “parallel program”. Activity ends in 1990 with the bilateral inspection agreements with Argentina. Way codes exploration from 1953 and pursuit from 1978."}, {"state": "IRQ", "src": "bleek", "page": 26, "text": "Bleek codes exploration from 1975 and a covert weapons program from 1981, after Israel bombed the Osiraq reactor, ending in 1991 when Iraq was forced after the Gulf War to give up its weapons of mass destruction and accept intrusive inspection."}, {"state": "IRQ", "src": "bleek", "page": 27, "text": "Bleek notes that the claims made before the 2003 war that Iraq was still pursuing nuclear weapons were weak and were debunked afterwards. The three datasets still end Iraq's program in different years: 1991 (Bleek), 1995 (Way) and 2002 (Jo and Gartzke)."}, {"state": "IRN", "src": "bleek", "page": 27, "text": "Bleek codes exploration from 1974 under the Shah, no activity after the 1979 revolution, exploration again from 1984 and pursuit from 1989 with no end date as of the paper’s 2017 publication, while noting a case for stepping Iran down after 2003 or after the 2015 JCPOA."}, {"state": "SYR", "src": "bleek", "page": 29, "text": "Bleek codes exploration from 2000, pursuit from 2002, when construction began at Al-Kibar with North Korean help, and a return to exploration after Israel destroyed the reactor on 6 September 2007. Way's 2012 update codes pursuit from 2000 with no end date."}, {"state": "SYR", "src": "iaea2011", "text": "In June 2011 the IAEA Board of Governors found that the building destroyed at Dair Alzour in September 2007 “was very likely a nuclear reactor” that Syria should have declared, and reported Syria's non-compliance to the UN Security Council."}, {"state": "DEU", "src": "bleek", "page": "31, 37", "text": "Bleek codes Nazi Germany as exploring from 1939 to 1945 but never pursuing; Jo and Gartzke code a program from 1941. Separately, Bleek codes West Germany exploring in 1957–58 through the secret Franco-German-Italian agreement that de Gaulle halted. This tool draws both episodes on one row."}, {"state": "JPN", "src": "bleek", "page": 31, "text": "Bleek codes wartime exploration from 1941 to 1945, and exploration again from 1967 to 1972, when at least five government-related studies weighed nuclear weapons and all favored reliance on U.S. extended deterrence. Jo and Gartzke code a wartime program from 1943; Bleek calls their main source sensationalistic."}, {"state": "CHE", "src": "bleek", "page": 33, "text": "Bleek codes exploration from 1945 to 1969, when Switzerland signed the NPT; it ratified in 1977. Military studies argued for nuclear weapons, but Bleek finds no outright pursuit."}, {"state": "SWE", "src": "bleek", "page": 34, "text": "Bleek codes exploration from 1945 to 1970, when Sweden acceded to the NPT; Sweden built an option but decided not to produce weapons. Jo and Gartzke code this as a program (pursuit) from 1946 to 1969."}, {"state": "NOR", "src": "bleek", "page": 34, "text": "Bleek codes exploration from 1947, when Norway decided to build a research reactor under the Ministry of Defense, to 1962, when the government said publicly it did not intend to acquire nuclear weapons. Neither Way nor Jo and Gartzke code Norway."}, {"state": "EGY", "src": "bleek", "page": 35, "text": "Bleek codes exploration from 1955 to 1980, when Egypt ratified the NPT after a commission reviewed whether it could and should build weapons. Way's 2012 file codes exploration 1960–1964 and pursuit 1965–1974; Jo and Gartzke code no program."}, {"state": "ITA", "src": "bleek", "page": 36, "text": "Bleek codes exploration in 1955–58: a military center for nuclear applications, then the 1957 secret agreement with France and West Germany, ended by de Gaulle in 1958."}, {"state": "AUS", "src": "bleek", "page": 37, "text": "Bleek codes exploration from 1956, as Australia sought weapons from Britain and later studied domestic production, until it signed the NPT in 1973. Way codes pursuit from 1961 to 1973; Jo and Gartzke treat Australia's part in the British program of the 1950s as not an independent project of its own."}, {"state": "IDN", "src": "bleek", "page": 38, "text": "Bleek codes exploration in 1964–67 on the strength of public claims by an army general and Sukarno that Indonesia would soon test a bomb, and notes there is little evidence of a real program."}, {"state": "TWN", "src": "bleek", "page": 39, "text": "Bleek codes exploration from 1967, when the defense ministry proposed a US$140 million weapons program, to 1976, when on 14 September Chiang Ching-kuo promised the U.S. ambassador that Taiwan would not acquire reprocessing facilities. A second episode runs 1987–88, when a hot-cell facility was built in violation of that pledge and stopped under U.S. pressure."}, {"state": "TWN", "src": "bleek", "page": "39–40", "text": "The datasets disagree on how far Taiwan went. Bleek codes exploration only and says there is a case for pursuit. Way codes the first episode as pursuit (1967–1977), and Jo and Gartzke code a program from 1967 to 1976 but no second episode."}, {"state": "ROU", "src": "bleek", "page": 42, "text": "Bleek's narrative codes exploration from 1965, when Ceaușescu came to power and Romania began seeking dual-use technology outside the Soviet Union, to his overthrow in 1989, and finds too little evidence for pursuit. His Table 1, which this tool draws, gives 1978–89 instead; the paper does not explain the difference. Jo and Gartzke code a program from 1981 to 1989; Way codes exploration from 1985 to 1990."}, {"state": "ARG", "src": "bleek", "page": 44, "text": "Bleek codes exploration from 1978, when Argentina decided to build a reprocessing plant and a clandestine enrichment plant, to the 1990 agreements with Brazil. Way codes pursuit from 1978 but advises also running analyses with exploration only."}, {"state": "DZA", "src": "bleek", "page": 44, "text": "Bleek codes exploration from 1983, when Algeria secretly agreed to buy a large research reactor from China, to 1991, when it put the reactor under IAEA safeguards. Way's file codes Algeria exploring from 1983 with no end date."}, {"state": "UKR", "src": "bleek", "page": 46, "text": "None of the three datasets codes Ukraine. Soviet nuclear weapons stayed on its territory after 1991, but Ukraine never had operational control of them; Bleek notes it reportedly explored how to gain control, which some would code as exploration."}, {"state": "UKR", "src": "budapest", "text": "In the Budapest Memorandum of 5 December 1994, Russia, the United Kingdom and the United States gave Ukraine security assurances in connection with its accession to the NPT as a non-nuclear-weapon state, noting its commitment to eliminate all nuclear weapons from its territory."}, {"state": "BLR", "src": "bleek", "page": 47, "text": "None of the three datasets codes Belarus. Soviet weapons remained on its soil after 1991, but Belarus never controlled them, and Bleek finds no evidence that it explored gaining control."}, {"state": "KAZ", "src": "bleek", "page": 47, "text": "None of the three datasets codes Kazakhstan. Soviet weapons remained on its soil after 1991, but Kazakhstan never controlled them, and Bleek finds no evidence that it explored gaining control."}];
